import React, { useState, useEffect } from 'react';
import { supabase } from './supabaseClient'; 
import DepartmentCard from './components/DepartmentCard';
import ScheduleCalendar from './components/ScheduleCalendar';
import ConflictTable from './components/ConflictTable';
import GlobalResourceMonitor from './components/GlobalResourceMonitor';
import { 
  LayoutDashboard, Printer, Activity, Zap, LogOut, Lock, User, RefreshCw 
} from 'lucide-react';

function App() {
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const [departments, setDepartments] = useState([]);
  const [globalSchedule, setGlobalSchedule] = useState([]);
  const [allExamDates, setAllExamDates] = useState([]);

  // --- 1. AUTHENTICATION & SYNC ---
  useEffect(() => {
    // Check current login status
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      if (session) fetchAllData();
      setLoading(false);
    });

    // Listen for sign-in or sign-out
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) fetchAllData();
      else {
        setDepartments([]);
        setGlobalSchedule([]);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // --- 2. DATA PERSISTENCE (GET/POST/DELETE) ---
  const fetchAllData = async () => {
    setLoading(true);
    try {
      const [deptsRes, schedsRes] = await Promise.all([
        supabase.from('departments').select('*').order('name', { ascending: true }),
        supabase.from('schedules').select('*')
      ]);

      if (deptsRes.data) setDepartments(deptsRes.data);
      if (schedsRes.data) {
        const dates = [...new Set(schedsRes.data.map(s => s.exam_date))].sort();
        setGlobalSchedule(runConflictDetection(schedsRes.data));
        setAllExamDates(dates);
      }
    } catch (err) {
      console.error("Cloud Sync Error:", err);
    } finally {
      setLoading(false);
    }
  };

  const updateDeptData = async (deptId, field, newData) => {
    // Update local state immediately for responsiveness
    setDepartments(prev => prev.map(d => d.id === deptId ? { ...d, [field]: newData } : d));
    // Save to Supabase
    await supabase.from('departments').update({ [field]: newData }).eq('id', deptId);
  };

  const addDepartment = async () => {
    const name = prompt("Enter Department Name:");
    const code = prompt("Enter Dept Code (e.g. CCS):");
    if (name && code) {
      const newDept = { 
        name, code: code.toUpperCase(),
        subjects: { 1: [], 2: [], 3: [], 4: [], 5: [] },
        proctors: [], rooms: []
      };
      const { data, error } = await supabase.from('departments').insert([newDept]).select();
      if (!error) setDepartments(prev => [...prev, data[0]]);
    }
  };

  const deleteDepartment = async (deptId, deptCode) => {
    if (window.confirm(`Delete ${deptCode} permanently?`)) {
      await supabase.from('departments').delete().eq('id', deptId);
      setDepartments(prev => prev.filter(d => d.id !== deptId));
      setGlobalSchedule(prev => prev.filter(item => item.dept_code !== deptCode));
    }
  };

  const handleScheduleGenerated = async (newAssignments, newDates, deptCode) => {
    const targetYear = newAssignments[0]?.year_level;

    // Remove old schedule for this year level from the cloud
    await supabase.from('schedules')
      .delete()
      .eq('dept_code', deptCode)
      .eq('year_level', targetYear);

    // Save new schedule to the cloud
    const { error } = await supabase.from('schedules').insert(newAssignments);

    if (!error) fetchAllData();
  };

  // --- 3. CONFLICT ENGINE ---
  const runConflictDetection = (scheduleList) => {
    return scheduleList.map(item => {
      const conflict = scheduleList.find(target => 
        target.id !== item.id && 
        target.exam_date === item.exam_date &&
        (target.room === item.room || target.proctor === item.proctor) &&
        (item.start_time < target.end_time && item.end_time > target.start_time)
      );
      return { 
        ...item, 
        hasConflict: !!conflict, 
        conflictType: conflict ? (conflict.room === item.room ? 'ROOM' : 'PROCTOR') : null 
      };
    });
  };

  // --- 4. LOGIN / SIGNUP UI ---
  const handleAuthAction = async (action) => {
    const { error } = action === 'LOGIN' 
      ? await supabase.auth.signInWithPassword({ email, password })
      : await supabase.auth.signUp({ email, password });

    if (error) alert(error.message);
    else if (action === 'SIGNUP') alert("Check your email for the verification link!");
  };

  if (!session) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6">
        <div className="bg-white w-full max-w-md rounded-[3.5rem] p-12 shadow-2xl">
          <div className="text-center mb-10">
            <div className="inline-flex bg-blue-600 p-5 rounded-[2rem] mb-6 text-white shadow-xl">
              <Lock size={32} />
            </div>
            <h1 className="text-3xl font-black uppercase italic tracking-tighter">Accord <span className="text-blue-600">Pro</span></h1>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-2">Shared Institutional Workspace</p>
          </div>
          <div className="space-y-4">
            <div className="relative group">
              <User className="absolute left-5 top-5 text-slate-300" size={18}/>
              <input type="email" placeholder="Email Address" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-slate-50 p-5 pl-14 rounded-2xl font-black text-xs border-2 border-slate-50 outline-none focus:border-blue-500 transition-all" />
            </div>
            <div className="relative group">
              <Lock className="absolute left-5 top-5 text-slate-300" size={18}/>
              <input type="password" placeholder="Password" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-slate-50 p-5 pl-14 rounded-2xl font-black text-xs border-2 border-slate-50 outline-none focus:border-blue-500 transition-all" />
            </div>
            <button onClick={() => handleAuthAction('LOGIN')} className="w-full bg-slate-900 text-white p-5 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-slate-800 active:scale-95 transition-all">Sign In</button>
            <button onClick={() => handleAuthAction('SIGNUP')} className="w-full text-slate-400 p-2 font-black uppercase text-[9px] tracking-widest hover:text-blue-600 transition-colors">Register Account</button>
          </div>
        </div>
      </div>
    );
  }

  const conflictCount = globalSchedule.filter(s => s.hasConflict).length;

  return (
    <div className="min-h-screen bg-slate-50 pb-24 font-sans text-slate-900">
      <nav className="bg-slate-900 px-8 py-5 mb-10 flex justify-between items-center sticky top-0 z-50 shadow-2xl">
        <div className="flex items-center gap-3 text-white font-black uppercase tracking-tighter text-xl">
          <LayoutDashboard size={28} className="text-blue-500" />
          ACCORD <span className="text-blue-500 italic">PRO</span>
        </div>

        <div className="flex items-center gap-6">
            <div className={`px-5 py-2 rounded-2xl border-2 flex items-center gap-2 text-[10px] font-black uppercase transition-all ${conflictCount > 0 ? 'bg-rose-500/10 border-rose-500/50 text-rose-500' : 'bg-emerald-500/10 border-emerald-500/50 text-emerald-500'}`}>
                <Activity size={14} className={conflictCount > 0 ? 'animate-pulse' : ''} />
                {conflictCount > 0 ? `${conflictCount} Conflicts` : 'Sync Active'}
            </div>
            <button onClick={addDepartment} className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-2.5 rounded-2xl font-black text-[10px] uppercase shadow-lg transition-all active:scale-95">Add Dept</button>
            <button onClick={() => supabase.auth.signOut()} className="bg-white/10 hover:bg-rose-500 text-white p-2.5 rounded-xl transition-all">
              <LogOut size={18} />
            </button>
        </div>
      </nav>

      <main className="container mx-auto px-6 max-w-7xl">
        {loading ? (
          <div className="flex flex-col items-center justify-center py-40">
             <RefreshCw size={48} className="text-blue-500 animate-spin mb-4" />
             <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Loading Database...</p>
          </div>
        ) : (
          <>
            <div className="grid grid-cols-1 gap-12 mb-16">
              <ConflictTable schedule={globalSchedule} />
              <GlobalResourceMonitor allDepartments={departments} globalSchedule={globalSchedule} />
            </div>

            <div className="space-y-16">
              {departments.map((dept) => (
                <DepartmentCard 
                  key={dept.id} 
                  dept={dept}
                  allDepartments={departments}
                  onUpdate={(field, data) => updateDeptData(dept.id, field, data)}
                  onDeleteDept={deleteDepartment}
                  onClearSchedule={(dCode, yLevel) => {
                    supabase.from('schedules').delete().eq('dept_code', dCode).eq('year_level', yLevel).then(() => fetchAllData());
                  }}
                  globalSchedule={globalSchedule}
                  onGenerate={(schedule, dates) => handleScheduleGenerated(schedule, dates, dept.code)}
                />
              ))}
            </div>

            <div className="mt-32 pt-24 border-t-4 border-slate-900/5">
                <div className="flex justify-between items-end mb-12 px-6">
                    <h2 className="text-6xl font-black text-slate-900 tracking-tighter">Master <span className="text-blue-600 italic">Timeline</span></h2>
                    <button onClick={() => window.print()} className="bg-slate-900 text-white px-10 py-5 rounded-[2.5rem] font-black text-[10px] uppercase tracking-widest flex items-center gap-3 transition-all active:scale-95 shadow-2xl">
                        <Printer size={20}/> Export Final PDF
                    </button>
                </div>
                <div className="bg-white p-4 rounded-[4rem] shadow-xl border border-slate-100">
                  {globalSchedule.length > 0 ? (
                    <ScheduleCalendar scheduleData={globalSchedule} examDates={allExamDates} />
                  ) : (
                    <div className="py-32 text-center text-slate-300 font-black uppercase tracking-[0.5em] text-sm">
                      <Zap size={48} className="mx-auto mb-4 opacity-20" /> No Data Found
                    </div>
                  )}
                </div>
            </div>
          </>
        )}
      </main>
    </div>
  );
}

export default App;
